variables.input:
timeseries n = count(zeebe.health), by: {k8s.namespace.name}
| fields k8s.namespace.name
| sort k8s.namespace.name asc

3.query:
timeseries send_per_sec = sum(atomix.raft.messages.send, rate:1s),
  by: {partition, to, type},
  filter: {in(k8s.namespace.name, array($Namespace))}

4.query:
timeseries send = avg(atomix.raft.messages.send, filter:{type == "InstallRequest"}),
  by: {k8s.pod.name, partition, type, to},
  filter: {in(k8s.namespace.name, array($Namespace))}

5.query:
timeseries entries_rate_per_sec = sum(atomix.commit.entries.rate, rate:1s),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

6.query:
timeseries data_rate_per_sec = sum(atomix.append.entries.data.rate, rate:1s),
  by: {partition, follower},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

7.query:
timeseries entries_rate_per_sec = sum(atomix.append.entries.rate, rate:1s),
  by: {partition, follower},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition))}

8.query:
timeseries milliseconds = avg(atomix.snapshot.replication.duration.milliseconds),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

9.query:
timeseries replication_count = avg(atomix.snapshot.replication.count),
  by: {k8s.pod.name, partitionGroupName, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

11.query:
timeseries {
    mean = avg(atomix.append.entries.latency),
    p50 = percentile(atomix.append.entries.latency, 50)
  },
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))},
  union: true

14.query:
timeseries role = avg(atomix.role),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

15.query:
timeseries role = avg(atomix.role),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

16.query:
timeseries commit_index = max(atomix.partition.raft.commit.index),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

17.query:
timeseries append_index = max(atomix.partition.raft.append.index),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

25.query:
timeseries inflight_requests = sum(zeebe.messaging.inflight.requests),
  by: {k8s.pod.name, address},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

26.query:
timeseries request_count_per_sec = sum(zeebe.messaging.request.count, rate:1s),
  by: {k8s.pod.name, address, topic},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

27.query:
timeseries response_count_per_sec = sum(zeebe.messaging.response.count, rate:1s, filter:{outcome != "SUCCESS"}),
  by: {address, topic, outcome},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

28.query:
timeseries request_count_per_sec = sum(zeebe.messaging.request.count, rate:1s),
  by: {type},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

30.query:
timeseries requests = sum(zeebe.gateway.total.requests),
  by: {requestType},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

46.query:
timeseries checkpoint_records = max(zeebe.checkpoint.records.total),
  by: {partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

51.query:
timeseries incarnation_number = avg(zeebe.smp.members.incarnation.number),
  by: {k8s.pod.name, memberId},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

53.query:
timeseries success_per_sec = sum(zeebe.dns.success, rate:1s),
  by: {k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

54.query:
timeseries failed_per_sec = sum(zeebe.dns.failed, rate:1s),
  by: {k8s.pod.name, code},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

55.query:
timeseries error_per_sec = sum(zeebe.dns.error, rate:1s),
  by: {k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}
